SELECT COALESCE(SUM(p.refund_amount), 0) FROM crm_paymentterm p
INNER JOIN crm_contract c ON c.contract_id = p.contract_id
WHERE c.contact_id = #{contactId}

SELECT COALESCE(SUM(p.paid_amount), 0) FROM crm_paymentterm p
INNER JOIN crm_contract c ON c.contract_id = p.contract_id
WHERE c.contact_id = #{contactId}

SELECT COALESCE(SUM(sub.sign_amount), 0) FROM (
    SELECT DISTINCT c.contract_id, COALESCE(c.sign_amount, c.total_amount, c.amount, 0) AS sign_amount
    FROM crm_contract c WHERE c.account_id = #{accountId}
) sub

SELECT COALESCE(SUM(p.refund_amount), 0) FROM crm_paymentterm p
INNER JOIN crm_contract c ON c.contract_id = p.contract_id
WHERE c.account_id = #{accountId}

SELECT COALESCE(SUM(p.paid_amount), 0) FROM crm_paymentterm p
INNER JOIN crm_contract c ON c.contract_id = p.contract_id
WHERE c.account_id = #{accountId}

SELECT * FROM ( SELECT 'event' AS campaign_type, e.event_id AS campaign_id, e.subject AS campaign_name, COALESCE(e.paid, 0) AS spend, COUNT(DISTINCT ac.contact_id)::integer AS converted_contacts, COALESCE(SUM(pv.net_clv), 0) AS converted_clv_total, CASE WHEN COUNT(DISTINCT ac.contact_id) > 0 THEN COALESCE(e.paid, 0) / COUNT(DISTINCT ac.contact_id) ELSE COALESCE(e.paid, 0) END AS cac_per_contact, CASE WHEN COALESCE(e.paid, 0) > 0 THEN (COALESCE(SUM(pv.net_clv), 0) - COALESCE(e.paid, 0)) / COALESCE(e.paid, 0) ELSE NULL END AS roi, MIN(e.create_time) AS first_activity_at, MAX(e.create_time) AS last_activity_at FROM crm_event e LEFT JOIN (
) ac ON ac.event_id = e.event_id LEFT JOIN crm_patient_value pv ON pv.contact_id = ac.contact_id AND pv.del_flag = '0' WHERE COALESCE(e.paid, 0) >= 0 AND e.create_time >= #{dateFrom} AND e.create_time <= #{dateTo} AND e.event_id = #{campaignId} GROUP BY e.event_id, e.subject, e.paid UNION ALL SELECT 'bulkemail', b.bulk_id, b.subject, COALESCE(b.spend_amount, 0), COUNT(DISTINCT l.contact_id)::integer, COALESCE(SUM(pv.net_clv), 0), CASE WHEN COUNT(DISTINCT l.contact_id) > 0 THEN COALESCE(b.spend_amount, 0) / COUNT(DISTINCT l.contact_id) ELSE COALESCE(b.spend_amount, 0) END, CASE WHEN COALESCE(b.spend_amount, 0) > 0 THEN (COALESCE(SUM(pv.net_clv), 0) - COALESCE(b.spend_amount, 0)) / COALESCE(b.spend_amount, 0) ELSE NULL END, MIN(ch.create_time), MAX(ch.create_time) FROM crm_bulkemail b LEFT JOIN crm_conversion_history ch ON ch.target_id = b.bulk_id AND ch.conversion_type = 'Email Marketing' LEFT JOIN crm_lead l ON l.lead_id = ch.lead_id AND l.contact_id IS NOT NULL AND l.contact_id != '' LEFT JOIN crm_patient_value pv ON pv.contact_id = l.contact_id AND pv.del_flag = '0' WHERE COALESCE(b.spend_amount, 0) >= 0 AND b.create_time >= #{dateFrom} AND b.create_time <= #{dateTo} GROUP BY b.bulk_id, b.subject, b.spend_amount ) campaigns WHERE 1=1
AND campaign_type = #{campaignType}
AND campaign_id = #{campaignId}
ORDER BY spend DESC

SELECT DISTINCT l.contact_id AS contact_id
FROM crm_conversion_history ch
INNER JOIN crm_lead l ON l.lead_id = ch.lead_id
WHERE ch.target_id = #{campaignId}
  AND ch.conversion_type = #{conversionType}
  AND l.contact_id IS NOT NULL AND l.contact_id != ''

mapper.update:
UPDATE crm_contact SET first_visit_at = #{firstVisitAt}, last_visit_at = #{lastVisitAt},
       visit_count = #{visitCount}, update_time = CURRENT_TIMESTAMP
WHERE contact_id = #{contactId}
